1	import type DiscourseGraphPlugin from "~/index";
2	import { uuidv7 } from "uuidv7";
3	import { parseDgSchemaFile } from "~/utils/specValidation";
4	import {
5	  createTemplateFile,
6	  createTemplateFileWithUniqueName,
7	  getTemplateFiles,
8	  readTemplateContent,
9	} from "~/utils/templates";
10	import { openJsonFromUserLocation } from "~/utils/nativeJsonFileDialogs";
11	import type {
12	  DiscourseNode,
13	  DiscourseRelation,
14	  DiscourseRelationType,
15	  DiscourseSchemaFile,
16	  SchemaSelection,
17	} from "~/types";
18	import { toTldrawColor } from "~/utils/tldrawColors";
19	import { canonicalObsidianUrl } from "~/utils/supabaseContext";
20	import {
21	  buildSchemaRid,
22	  findExistingTriple,
23	  findLocalNodeTypeMatch,
24	  findLocalRelationTypeMatch,
25	  type SchemaImportMatchPlan,
26	} from "~/utils/schemaMatching";
27	import {
28	  buildSchemaConflicts,
29	  MERGEABLE_NODE_TYPE_FIELDS,
30	  MERGEABLE_RELATION_TYPE_FIELDS,
31	  type SchemaConflict,
32	} from "~/utils/schemaFieldDiff";
33	
34	export type { SchemaImportMatchPlan };
35	
36	/** Keyed by schema-file id, templates by name, since two schema ids can share one local id. An absent entry keeps the local value. */
37	export type SchemaMergePlan = {
38	  nodeTypeFields: ReadonlyMap<string, ReadonlySet<string>>;
39	  relationTypeFields: ReadonlyMap<string, ReadonlySet<string>>;
40	  templateNames: ReadonlySet<string>;
41	};
42	
43	export type LoadedSchemaFile = {
44	  sourcePath: string;
45	  schemaFile: DiscourseSchemaFile;
46	  matchPlan: SchemaImportMatchPlan;
47	};
48	
49	export type ImportPreviewStats = {
50	  nodeTypes: { total: number; new: number; existing: number };
51	  relationTypes: { total: number; new: number; existing: number };
52	  discourseRelations: { total: number; new: number; existing: number };
53	  templates: { total: number; new: number; existing: number };
54	};
55	
56	export type SpecImportPreview = {
57	  loadedSchemaFile: LoadedSchemaFile;
58	  previewStats: ImportPreviewStats;
59	  conflicts: SchemaConflict[];
60	};
61	
62	/** Relation triples are absent from `merged` because endpoints are their identity. */
63	export type SpecImportApplyResult = {
64	  created: {
65	    nodeTypes: number;
66	    relationTypes: number;
67	    discourseRelations: number;
68	    templates: number;
69	  };
70	  merged: {
71	    nodeTypes: number;
72	    relationTypes: number;
73	    templates: number;
74	  };
75	};
76	
77	const buildSchemaImportMatchPlan = ({
78	  schemaFile,
79	  localNodeTypes,
80	  localRelationTypes,
81	  localDiscourseRelations,
82	  localTemplateNames,
83	}: {
84	  schemaFile: DiscourseSchemaFile;
85	  localNodeTypes: DiscourseNode[];
86	  localRelationTypes: DiscourseRelationType[];
87	  localDiscourseRelations: DiscourseRelation[];
88	  localTemplateNames: Set<string>;
89	}): SchemaImportMatchPlan => {
90	  const nodeTypeIdMapping = new Map<string, string>();
91	  const existingNodeTypeIds = new Set<string>();
92	  const collapsedNodeTypeIds = new Set<string>();
93	  const localNodeTypeIds = new Set(
94	    localNodeTypes.map((nodeType) => nodeType.id),
95	  );
96	  // Grows as types are planned, so "Event" and "event" in one file collapse instead of creating two.
97	  const knownNodeTypes = [...localNodeTypes];
98	
99	  for (const nodeType of schemaFile.nodeTypes) {
100	    const localMatch = findLocalNodeTypeMatch({
101	      localNodeTypes: knownNodeTypes,
102	      id: nodeType.id,
103	      name: nodeType.name,
104	    });
105	    if (localMatch) {
106	      nodeTypeIdMapping.set(nodeType.id, localMatch.id);
107	      existingNodeTypeIds.add(nodeType.id);
108	      // Matched a type planned earlier in this file, not one the vault holds.
109	      if (!localNodeTypeIds.has(localMatch.id)) {
110	        collapsedNodeTypeIds.add(nodeType.id);
111	      }
112	      continue;
113	    }
114	
115	    nodeTypeIdMapping.set(nodeType.id, nodeType.id);
116	    knownNodeTypes.push(nodeType);
117	  }
118	
119	  const relationTypeIdMapping = new Map<string, string>();
120	  const existingRelationTypeIds = new Set<string>();
121	  const collapsedRelationTypeIds = new Set<string>();
122	  const localRelationTypeIds = new Set(
123	    localRelationTypes.map((relationType) => relationType.id),
124	  );
125	  const knownRelationTypes = [...localRelationTypes];
126	
127	  for (const relationType of schemaFile.relationTypes) {
128	    const localMatch = findLocalRelationTypeMatch({
129	      localRelationTypes: knownRelationTypes,
130	      id: relationType.id,
131	      label: relationType.label,
132	    });
133	    if (localMatch) {
134	      relationTypeIdMapping.set(relationType.id, localMatch.id);
135	      existingRelationTypeIds.add(relationType.id);
136	      if (!localRelationTypeIds.has(localMatch.id)) {
137	        collapsedRelationTypeIds.add(relationType.id);
138	      }
139	      continue;
140	    }
141	
142	    relationTypeIdMapping.set(relationType.id, relationType.id);
143	    knownRelationTypes.push(relationType);
144	  }
145	
146	  const existingDiscourseRelationIds = new Set<string>();
147	  for (const relation of schemaFile.discourseRelations) {
148	    const existing = findExistingTriple({
149	      discourseRelations: localDiscourseRelations,
150	      sourceId: nodeTypeIdMapping.get(relation.sourceId) ?? relation.sourceId,
151	      destinationId:
152	        nodeTypeIdMapping.get(relation.destinationId) ?? relation.destinationId,
153	      relationshipTypeId:
154	        relationTypeIdMapping.get(relation.relationshipTypeId) ??
155	        relation.relationshipTypeId,
156	    });
157	    if (existing) {
158	      existingDiscourseRelationIds.add(relation.id);
159	    }
160	  }
161	
162	  const existingTemplateNames = new Set<string>();
163	  for (const template of schemaFile.templates) {
164	    if (localTemplateNames.has(template.name)) {
165	      existingTemplateNames.add(template.name);
166	    }
167	  }
168	
169	  return {
170	    nodeTypeIdMapping,
171	    relationTypeIdMapping,
172	    existingNodeTypeIds,
173	    existingRelationTypeIds,
174	    collapsedNodeTypeIds,
175	    collapsedRelationTypeIds,
176	    existingDiscourseRelationIds,
177	    existingTemplateNames,
178	    localTemplateNames,
179	  };
180	};
181	
182	const buildPreviewStats = ({
183	  schemaFile,
184	  matchPlan,
185	}: {
186	  schemaFile: DiscourseSchemaFile;
187	  matchPlan: SchemaImportMatchPlan;
188	}): ImportPreviewStats => {
189	  return {
190	    // A collapsed id is neither created nor held by the vault, so counting it as existing would name a type the user does not have.
191	    nodeTypes: {
192	      total: schemaFile.nodeTypes.length - matchPlan.collapsedNodeTypeIds.size,
193	      existing:
194	        matchPlan.existingNodeTypeIds.size -
195	        matchPlan.collapsedNodeTypeIds.size,
196	      new: schemaFile.nodeTypes.length - matchPlan.existingNodeTypeIds.size,
197	    },
198	    relationTypes: {
199	      total:
200	        schemaFile.relationTypes.length -
201	        matchPlan.collapsedRelationTypeIds.size,
202	      existing:
203	        matchPlan.existingRelationTypeIds.size -
204	        matchPlan.collapsedRelationTypeIds.size,
205	      new:
206	        schemaFile.relationTypes.length -
207	        matchPlan.existingRelationTypeIds.size,
208	    },
209	    discourseRelations: {
210	      total: schemaFile.discourseRelations.length,
211	      existing: matchPlan.existingDiscourseRelationIds.size,
212	      new:
213	        schemaFile.discourseRelations.length -
214	        matchPlan.existingDiscourseRelationIds.size,
215	    },
216	    templates: {
217	      total: schemaFile.templates.length,
218	      existing: matchPlan.existingTemplateNames.size,
219	      new: schemaFile.templates.length - matchPlan.existingTemplateNames.size,
220	    },
221	  };
222	};
223	
224	const readOverlappingTemplateContents = async ({
225	  plugin,
226	  matchPlan,
227	}: {
228	  plugin: DiscourseGraphPlugin;
229	  matchPlan: SchemaImportMatchPlan;
230	}): Promise<Map<string, string>> => {
231	  const entries = await Promise.all(
232	    [...matchPlan.existingTemplateNames].map(async (templateName) => {
233	      const content = await readTemplateContent({
234	        app: plugin.app,
235	        templateName,
236	      });
237	      return content === null ? [] : [[templateName, content] as const];
238	    }),
239	  );
240	  return new Map(entries.flat());
241	};
242	
243	export const pickAndPreviewSchemaImport = async ({
244	  plugin,
245	}: {
246	  plugin: DiscourseGraphPlugin;
247	}): Promise<SpecImportPreview> => {
248	  const file = await openJsonFromUserLocation({
249	    title: "Import discourse graph schema",
250	  });
251	  const schemaFile = parseDgSchemaFile(JSON.parse(file.content) as unknown);
252	  const localTemplateNames = new Set(getTemplateFiles(plugin.app));
253	  const matchPlan = buildSchemaImportMatchPlan({
254	    schemaFile,
255	    localNodeTypes: plugin.settings.nodeTypes,
256	    localRelationTypes: plugin.settings.relationTypes,
257	    localDiscourseRelations: plugin.settings.discourseRelations,
258	    localTemplateNames,
259	  });
260	
261	  const loadedSchemaFile: LoadedSchemaFile = {
262	    sourcePath: file.sourcePath,
263	    schemaFile,
264	    matchPlan,
265	  };
266	
267	  const localTemplateContents = await readOverlappingTemplateContents({
268	    plugin,
269	    matchPlan,
270	  });
271	
272	  return {
273	    loadedSchemaFile,
274	    previewStats: buildPreviewStats({ schemaFile, matchPlan }),
275	    conflicts: buildSchemaConflicts({
276	      schemaFile,
277	      matchPlan,
278	      localNodeTypes: plugin.settings.nodeTypes,
279	      localRelationTypes: plugin.settings.relationTypes,
280	      localTemplateContents,
281	    }),
282	  };
283	};
284	
285	/** Keyed off what actually landed, so a failed creation leaves no dangling reference; an imported copy wins over a same-named local one. */
286	const resolveTemplateReference = ({
287	  template,
288	  importedTemplateNames,
289	  localTemplateNames,
290	}: {
291	  template: string | undefined;
292	  importedTemplateNames: ReadonlyMap<string, string>;
293	  localTemplateNames: ReadonlySet<string>;
294	}): string | undefined => {
295	  if (!template) return undefined;
296	  const importedName = importedTemplateNames.get(template);
297	  if (importedName) return importedName;
298	  return localTemplateNames.has(template) ? template : undefined;
299	};
300	
301	const mergeNodeTypeFields = ({
302	  local,
303	  imported,
304	  fields,
305	  importedTemplateNames,
306	  localTemplateNames,
307	}: {
308	  local: DiscourseNode;
309	  imported: DiscourseNode;
310	  fields: ReadonlySet<string>;
311	  importedTemplateNames: ReadonlyMap<string, string>;
312	  localTemplateNames: ReadonlySet<string>;
313	}): DiscourseNode => {
314	  const merged: DiscourseNode = { ...local, modified: Date.now() };
315	  for (const field of MERGEABLE_NODE_TYPE_FIELDS) {
316	    if (!fields.has(field)) continue;
317	    // TS cannot correlate merged[field] with imported[field] across a key union; the `satisfies` clause makes the write sound.
318	    (merged as Record<string, unknown>)[field] = imported[field];
319	  }
320	  // Same guard the create path applies, so a merged reference cannot dangle.
321	  if (fields.has("template")) {
322	    merged.template = resolveTemplateReference({
323	      template: merged.template,
324	      importedTemplateNames,
325	      localTemplateNames,
326	    });
327	  } else if (merged.template) {
328	    // Both sides naming the same template yields no `template` change row, so the reference must still follow a chosen imported body into its renamed copy.
329	    merged.template =
330	      importedTemplateNames.get(merged.template) ?? merged.template;
331	  }
332	  return merged;
333	};
334	
335	const mergeRelationTypeFields = ({
336	  local,
337	  imported,
338	  fields,
339	}: {
340	  local: DiscourseRelationType;
341	  imported: DiscourseRelationType;
342	  fields: ReadonlySet<string>;
343	}): DiscourseRelationType => {
344	  const merged: DiscourseRelationType = { ...local, modified: Date.now() };
345	  for (const field of MERGEABLE_RELATION_TYPE_FIELDS) {
346	    if (!fields.has(field)) continue;
347	    (merged as Record<string, unknown>)[field] = imported[field];
348	  }
349	  if (fields.has("color")) {
350	    merged.color = toTldrawColor(merged.color);
351	  }
352	  return merged;
353	};
354	
355	export const applySchemaImportSelection = async ({
356	  plugin,
357	  loadedSchemaFile,
358	  selection,
359	  mergePlan,
360	  onWarning = () => {},
361	}: {
362	  plugin: DiscourseGraphPlugin;
363	  loadedSchemaFile: LoadedSchemaFile;
364	  selection: SchemaSelection;
365	  mergePlan?: SchemaMergePlan;
366	  onWarning?: (message: string) => void;
367	}): Promise<SpecImportApplyResult> => {
368	  const { schemaFile, matchPlan } = loadedSchemaFile;
369	  const sourceSpaceUri = canonicalObsidianUrl(schemaFile.vaultId);
370	  const selectedTemplateNames = new Set(selection.templateNames);
371	  const selectedNodeTypeIds = new Set(selection.nodeTypeIds);
372	  const selectedRelationTypeIds = new Set(selection.relationTypeIds);
373	  const selectedRelationIds = new Set(selection.discourseRelationIds);
374	
375	  let templatesCreated = 0;
376	  let templatesMerged = 0;
377	  /** Schema-file template name to the name it actually landed under; these differ when the copy sits beside a local template. */
378	  const importedTemplateNames = new Map<string, string>();
379	  const templatesByName = new Map(
380	    schemaFile.templates.map((template) => [template.name, template]),
381	  );
382	  for (const templateName of selectedTemplateNames) {
383	    const template = templatesByName.get(templateName);
384	    if (!template) {
385	      onWarning(
386	        `Template "${templateName}" was selected but not found in schema file.`,
387	      );
388	      continue;
389	    }
390	
391	    if (matchPlan.existingTemplateNames.has(templateName)) {
392	      if (!mergePlan?.templateNames.has(templateName)) {
393	        continue;
394	      }
395	
396	      // Never clobber the local template: the copy lands beside it and the node type is repointed at the copy.
397	      const copyResult = await createTemplateFileWithUniqueName({
398	        app: plugin.app,
399	        templateName: template.name,
400	        sourceName: schemaFile.vaultName,
401	        content: template.content,
402	      });
403	      if (copyResult.created) {
404	        importedTemplateNames.set(template.name, copyResult.templateName);
405	        templatesMerged += 1;
406	      } else {
407	        onWarning(
408	          `Template "${template.name}" not imported: ${copyResult.reason}.`,
409	        );
410	      }
411	      continue;
412	    }
413	
414	    const result = await createTemplateFile({
415	      app: plugin.app,
416	      templateName: template.name,
417	      content: template.content,
418	    });
419	
420	    if (result.created) {
421	      // The landed basename, not the requested name: creation sanitizes, and a node type referencing the unsanitized name would resolve to no file.
422	      importedTemplateNames.set(template.name, result.templateName);
423	      templatesCreated += 1;
424	      continue;
425	    }
426	
427	    if (result.reason !== "template already exists") {
428	      onWarning(`Template "${template.name}" skipped: ${result.reason}.`);
429	    }
430	  }
431	
432	  const schemaNodeTypesById = new Map(
433	    schemaFile.nodeTypes.map((nodeType) => [nodeType.id, nodeType]),
434	  );
435	  const schemaRelationTypesById = new Map(
436	    schemaFile.relationTypes.map((relationType) => [
437	      relationType.id,
438	      relationType,
439	    ]),
440	  );
441	
442	  /** Where each schema id actually ended up, which diverges from the plan when settings moved since the preview. */
443	  const effectiveNodeTypeIds = new Map<string, string>();
444	  let nodeTypesCreated = 0;
445	  let nodeTypesMerged = 0;
446	  for (const nodeTypeId of selectedNodeTypeIds) {
447	    const importedNodeType = schemaNodeTypesById.get(nodeTypeId);
448	    if (!importedNodeType) {
449	      onWarning(
450	        `Node type "${nodeTypeId}" was selected but missing from schema file.`,
451	      );
452	      continue;
453	    }
454	
455	    // Re-matched against live settings rather than the plan: the plan is a preview-time snapshot, and an entry that collapsed onto another file entry has nothing to merge into unless that entry was also selected.
456	    const localMatch = findLocalNodeTypeMatch({
457	      localNodeTypes: plugin.settings.nodeTypes,
458	      id: matchPlan.nodeTypeIdMapping.get(nodeTypeId) ?? nodeTypeId,
459	      name: importedNodeType.name,
460	    });
461	
462	    if (localMatch) {
463	      effectiveNodeTypeIds.set(nodeTypeId, localMatch.id);
464	      const mergedFields = mergePlan?.nodeTypeFields.get(nodeTypeId);
465	      if (!mergedFields?.size) {
466	        continue;
467	      }
468	
469	      const localIndex = plugin.settings.nodeTypes.indexOf(localMatch);
470	      const nextNodeTypes = [...plugin.settings.nodeTypes];
471	      const mergedNodeType = mergeNodeTypeFields({
472	        local: nextNodeTypes[localIndex]!,
473	        imported: importedNodeType,
474	        fields: mergedFields,
475	        importedTemplateNames,
476	        localTemplateNames: matchPlan.localTemplateNames,
477	      });
478	      if (
479	        mergedFields.has("template") &&
480	        importedNodeType.template &&
481	        !mergedNodeType.template
482	      ) {
483	        onWarning(
484	          `Template "${importedNodeType.template}" was not imported and is not in this vault, so "${mergedNodeType.name}" was merged without a template reference.`,
485	        );
486	      }
487	      nextNodeTypes[localIndex] = mergedNodeType;
488	      plugin.settings.nodeTypes = nextNodeTypes;
489	      nodeTypesMerged += 1;
490	      continue;
491	    }
492	
493	    effectiveNodeTypeIds.set(nodeTypeId, importedNodeType.id);
494	    const newNodeType: DiscourseNode = {
495	      ...importedNodeType,
496	      template: resolveTemplateReference({
497	        template: importedNodeType.template,
498	        importedTemplateNames,
499	        localTemplateNames: matchPlan.localTemplateNames,
500	      }),
501	      importedFromRid: buildSchemaRid({
502	        spaceUri: sourceSpaceUri,
503	        localId: importedNodeType.id,
504	      }),
505	      modified: Date.now(),
506	    };
507	    plugin.settings.nodeTypes = [...plugin.settings.nodeTypes, newNodeType];
508	    nodeTypesCreated += 1;
509	  }
510	
511	  const effectiveRelationTypeIds = new Map<string, string>();
512	  let relationTypesCreated = 0;
513	  let relationTypesMerged = 0;
514	  for (const relationTypeId of selectedRelationTypeIds) {
515	    const importedRelationType = schemaRelationTypesById.get(relationTypeId);
516	    if (!importedRelationType) {
517	      onWarning(
518	        `Relation type "${relationTypeId}" was selected but missing from schema file.`,
519	      );
520	      continue;
521	    }
522	
523	    const localMatch = findLocalRelationTypeMatch({
524	      localRelationTypes: plugin.settings.relationTypes,
525	      id: matchPlan.relationTypeIdMapping.get(relationTypeId) ?? relationTypeId,
526	      label: importedRelationType.label,
527	    });
528	
529	    if (localMatch) {
530	      effectiveRelationTypeIds.set(relationTypeId, localMatch.id);
531	      const mergedFields = mergePlan?.relationTypeFields.get(relationTypeId);
532	      if (!mergedFields?.size) {
533	        continue;
534	      }
535	
536	      const localIndex = plugin.settings.relationTypes.indexOf(localMatch);
537	      const nextRelationTypes = [...plugin.settings.relationTypes];
538	      nextRelationTypes[localIndex] = mergeRelationTypeFields({
539	        local: nextRelationTypes[localIndex]!,
540	        imported: importedRelationType,
541	        fields: mergedFields,
542	      });
543	      plugin.settings.relationTypes = nextRelationTypes;
544	      relationTypesMerged += 1;
545	      continue;
546	    }
547	
548	    effectiveRelationTypeIds.set(relationTypeId, importedRelationType.id);
549	    const newRelationType: DiscourseRelationType = {
550	      ...importedRelationType,
551	      color: toTldrawColor(importedRelationType.color),
552	      importedFromRid: buildSchemaRid({
553	        spaceUri: sourceSpaceUri,
554	        localId: importedRelationType.id,
555	      }),
556	      // Accepted, not provisional: the user chose this file and hand-picked these items, so nothing is left to review.
557	      status: "accepted",
558	      modified: Date.now(),
559	    };
560	    plugin.settings.relationTypes = [
561	      ...plugin.settings.relationTypes,
562	      newRelationType,
563	    ];
564	    relationTypesCreated += 1;
565	  }
566	
567	  const hasNodeType = (id: string): boolean =>
568	    plugin.settings.nodeTypes.some((nodeType) => nodeType.id === id);
569	  const hasRelationType = (id: string): boolean =>
570	    plugin.settings.relationTypes.some(
571	      (relationType) => relationType.id === id,
572	    );
573	
574	  let discourseRelationsCreated = 0;
575	  for (const relation of schemaFile.discourseRelations) {
576	    if (!selectedRelationIds.has(relation.id)) {
577	      continue;
578	    }
579	
580	    // Where the endpoint actually landed takes precedence over the plan, which can name a type this run never created.
581	    const mappedSourceId =
582	      effectiveNodeTypeIds.get(relation.sourceId) ??
583	      matchPlan.nodeTypeIdMapping.get(relation.sourceId) ??
584	      relation.sourceId;
585	    const mappedDestinationId =
586	      effectiveNodeTypeIds.get(relation.destinationId) ??
587	      matchPlan.nodeTypeIdMapping.get(relation.destinationId) ??
588	      relation.destinationId;
589	    const mappedRelationTypeId =
590	      effectiveRelationTypeIds.get(relation.relationshipTypeId) ??
591	      matchPlan.relationTypeIdMapping.get(relation.relationshipTypeId) ??
592	      relation.relationshipTypeId;
593	
594	    // Checked against live settings, not the plan: two file relations can map to one triple after collapsing.
595	    const alreadyPresent = findExistingTriple({
596	      discourseRelations: plugin.settings.discourseRelations,
597	      sourceId: mappedSourceId,
598	      destinationId: mappedDestinationId,
599	      relationshipTypeId: mappedRelationTypeId,
600	    });
601	    if (alreadyPresent) {
602	      continue;
603	    }
604	
605	    // The selection UI keeps a triple's endpoints selected, but this layer owns settings integrity, so a dangling triple is refused rather than written.
606	    if (
607	      !hasNodeType(mappedSourceId) ||
608	      !hasNodeType(mappedDestinationId) ||
609	      !hasRelationType(mappedRelationTypeId)
610	    ) {
611	      const sourceName =
612	        schemaNodeTypesById.get(relation.sourceId)?.name ?? relation.sourceId;
613	      const destinationName =
614	        schemaNodeTypesById.get(relation.destinationId)?.name ??
615	        relation.destinationId;
616	      const relationLabel =
617	        schemaRelationTypesById.get(relation.relationshipTypeId)?.label ??
618	        relation.relationshipTypeId;
619	      onWarning(
620	        `Relation "${sourceName} ${relationLabel} ${destinationName}" skipped: it references a type that is not in this vault.`,
621	      );
622	      continue;
623	    }
624	
625	    const newRelation: DiscourseRelation = {
626	      ...relation,
627	      id: uuidv7(),
628	      sourceId: mappedSourceId,
629	      destinationId: mappedDestinationId,
630	      relationshipTypeId: mappedRelationTypeId,
631	      importedFromRid: buildSchemaRid({
632	        spaceUri: sourceSpaceUri,
633	        localId: relation.id,
634	      }),
635	      status: "accepted",
636	      modified: Date.now(),
637	    };
638	    plugin.settings.discourseRelations = [
639	      ...plugin.settings.discourseRelations,
640	      newRelation,
641	    ];
642	    discourseRelationsCreated += 1;
643	  }
644	
645	  await plugin.saveSettings();
646	
647	  return {
648	    created: {
649	      nodeTypes: nodeTypesCreated,
650	      relationTypes: relationTypesCreated,
651	      discourseRelations: discourseRelationsCreated,
652	      templates: templatesCreated,
653	    },
654	    merged: {
655	      nodeTypes: nodeTypesMerged,
656	      relationTypes: relationTypesMerged,
657	      templates: templatesMerged,
658	    },
659	  };
660	};
