1	import type DiscourseGraphPlugin from "~/index";
2	import { uuidv7 } from "uuidv7";
3	import { parseDgSchemaFile } from "~/utils/specValidation";
4	import {
5	  createTemplateFile,
6	  createTemplateFileWithUniqueName,
7	  getTemplateFiles,
8	  readTemplateContent,
9	} from "~/utils/templates";
10	import { openJsonFromUserLocation } from "~/utils/nativeJsonFileDialogs";
11	import type {
12	  DiscourseNode,
13	  DiscourseRelation,
14	  DiscourseRelationType,
15	  DiscourseSchemaFile,
16	  SchemaSelection,
17	} from "~/types";
18	import { toTldrawColor } from "~/utils/tldrawColors";
19	import { canonicalObsidianUrl } from "~/utils/supabaseContext";
20	import {
21	  buildSchemaRid,
22	  findExistingTriple,
23	  findLocalNodeTypeMatch,
24	  findLocalRelationTypeMatch,
25	  type SchemaImportMatchPlan,
26	} from "~/utils/schemaMatching";
27	import {
28	  buildSchemaConflicts,
29	  MERGEABLE_NODE_TYPE_FIELDS,
30	  MERGEABLE_RELATION_TYPE_FIELDS,
31	  type SchemaConflict,
32	} from "~/utils/schemaFieldDiff";
33	
34	export type { SchemaImportMatchPlan };
35	
36	/** Keyed by schema-file id, templates by name, since two schema ids can share one local id. An absent entry keeps the local value. */
37	export type SchemaMergePlan = {
38	  nodeTypeFields: ReadonlyMap<string, ReadonlySet<string>>;
39	  relationTypeFields: ReadonlyMap<string, ReadonlySet<string>>;
40	  templateNames: ReadonlySet<string>;
41	};
42	
43	export type LoadedSchemaFile = {
44	  sourcePath: string;
45	  schemaFile: DiscourseSchemaFile;
46	  matchPlan: SchemaImportMatchPlan;
47	};
48	
49	export type ImportPreviewStats = {
50	  nodeTypes: { total: number; new: number; existing: number };
51	  relationTypes: { total: number; new: number; existing: number };
52	  discourseRelations: { total: number; new: number; existing: number };
53	  templates: { total: number; new: number; existing: number };
54	};
55	
56	export type SpecImportPreview = {
57	  loadedSchemaFile: LoadedSchemaFile;
58	  previewStats: ImportPreviewStats;
59	  conflicts: SchemaConflict[];
60	};
61	
62	/** Relation triples are absent from `merged` because endpoints are their identity. */
63	export type SpecImportApplyResult = {
64	  created: {
65	    nodeTypes: number;
66	    relationTypes: number;
67	    discourseRelations: number;
68	    templates: number;
69	  };
70	  merged: {
71	    nodeTypes: number;
72	    relationTypes: number;
73	    templates: number;
74	  };
75	};
76	
77	const buildSchemaImportMatchPlan = ({
78	  schemaFile,
79	  localNodeTypes,
80	  localRelationTypes,
81	  localDiscourseRelations,
82	  localTemplateNames,
83	}: {
84	  schemaFile: DiscourseSchemaFile;
85	  localNodeTypes: DiscourseNode[];
86	  localRelationTypes: DiscourseRelationType[];
87	  localDiscourseRelations: DiscourseRelation[];
88	  localTemplateNames: Set<string>;
89	}): SchemaImportMatchPlan => {
90	  const nodeTypeIdMapping = new Map<string, string>();
91	  const existingNodeTypeIds = new Set<string>();
92	  const collapsedNodeTypeIds = new Set<string>();
93	  const localNodeTypeIds = new Set(
94	    localNodeTypes.map((nodeType) => nodeType.id),
95	  );
96	  // Grows as types are planned, so "Event" and "event" in one file collapse instead of creating two.
97	  const knownNodeTypes = [...localNodeTypes];
98	
99	  for (const nodeType of schemaFile.nodeTypes) {
100	    const localMatch = findLocalNodeTypeMatch({
101	      localNodeTypes: knownNodeTypes,
102	      id: nodeType.id,
103	      name: nodeType.name,
104	    });
105	    if (localMatch) {
106	      nodeTypeIdMapping.set(nodeType.id, localMatch.id);
107	      existingNodeTypeIds.add(nodeType.id);
108	      // Matched a type planned earlier in this file, not one the vault holds.
109	      if (!localNodeTypeIds.has(localMatch.id)) {
110	        collapsedNodeTypeIds.add(nodeType.id);
111	      }
112	      continue;
113	    }
114	
115	    nodeTypeIdMapping.set(nodeType.id, nodeType.id);
116	    knownNodeTypes.push(nodeType);
117	  }
118	
119	  const relationTypeIdMapping = new Map<string, string>();
120	  const existingRelationTypeIds = new Set<string>();
121	  const collapsedRelationTypeIds = new Set<string>();
122	  const localRelationTypeIds = new Set(
123	    localRelationTypes.map((relationType) => relationType.id),
124	  );
125	  const knownRelationTypes = [...localRelationTypes];
126	
127	  for (const relationType of schemaFile.relationTypes) {
128	    const localMatch = findLocalRelationTypeMatch({
129	      localRelationTypes: knownRelationTypes,
130	      id: relationType.id,
131	      label: relationType.label,
132	    });
133	    if (localMatch) {
134	      relationTypeIdMapping.set(relationType.id, localMatch.id);
135	      existingRelationTypeIds.add(relationType.id);
136	      if (!localRelationTypeIds.has(localMatch.id)) {
137	        collapsedRelationTypeIds.add(relationType.id);
138	      }
139	      continue;
140	    }
141	
142	    relationTypeIdMapping.set(relationType.id, relationType.id);
143	    knownRelationTypes.push(relationType);
144	  }
145	
146	  const existingDiscourseRelationIds = new Set<string>();
147	  for (const relation of schemaFile.discourseRelations) {
148	    const existing = findExistingTriple({
149	      discourseRelations: localDiscourseRelations,
150	      sourceId: nodeTypeIdMapping.get(relation.sourceId) ?? relation.sourceId,
151	      destinationId:
152	        nodeTypeIdMapping.get(relation.destinationId) ?? relation.destinationId,
153	      relationshipTypeId:
154	        relationTypeIdMapping.get(relation.relationshipTypeId) ??
155	        relation.relationshipTypeId,
156	    });
157	    if (existing) {
158	      existingDiscourseRelationIds.add(relation.id);
159	    }
160	  }
161	
162	  const existingTemplateNames = new Set<string>();
163	  for (const template of schemaFile.templates) {
164	    if (localTemplateNames.has(template.name)) {
165	      existingTemplateNames.add(template.name);
166	    }
167	  }
168	
169	  return {
170	    nodeTypeIdMapping,
171	    relationTypeIdMapping,
172	    existingNodeTypeIds,
173	    existingRelationTypeIds,
174	    collapsedNodeTypeIds,
175	    collapsedRelationTypeIds,
176	    existingDiscourseRelationIds,
177	    existingTemplateNames,
178	    localTemplateNames,
179	  };
180	};
181	
182	const buildPreviewStats = ({
183	  schemaFile,
184	  matchPlan,
185	}: {
186	  schemaFile: DiscourseSchemaFile;
187	  matchPlan: SchemaImportMatchPlan;
188	}): ImportPreviewStats => {
189	  return {
190	    // A collapsed id is neither created nor held by the vault, so counting it as existing would name a type the user does not have.
191	    nodeTypes: {
192	      total: schemaFile.nodeTypes.length - matchPlan.collapsedNodeTypeIds.size,
193	      existing:
194	        matchPlan.existingNodeTypeIds.size -
195	        matchPlan.collapsedNodeTypeIds.size,
196	      new: schemaFile.nodeTypes.length - matchPlan.existingNodeTypeIds.size,
197	    },
198	    relationTypes: {
199	      total:
200	        schemaFile.relationTypes.length -
201	        matchPlan.collapsedRelationTypeIds.size,
202	      existing:
203	        matchPlan.existingRelationTypeIds.size -
204	        matchPlan.collapsedRelationTypeIds.size,
205	      new:
206	        schemaFile.relationTypes.length -
207	        matchPlan.existingRelationTypeIds.size,
208	    },
209	    discourseRelations: {
210	      total: schemaFile.discourseRelations.length,
211	      existing: matchPlan.existingDiscourseRelationIds.size,
212	      new:
213	        schemaFile.discourseRelations.length -
214	        matchPlan.existingDiscourseRelationIds.size,
215	    },
216	    templates: {
217	      total: schemaFile.templates.length,
218	      existing: matchPlan.existingTemplateNames.size,
219	      new: schemaFile.templates.length - matchPlan.existingTemplateNames.size,
220	    },
221	  };
222	};
223	
224	const readOverlappingTemplateContents = async ({
225	  plugin,
226	  matchPlan,
227	}: {
228	  plugin: DiscourseGraphPlugin;
229	  matchPlan: SchemaImportMatchPlan;
230	}): Promise<Map<string, string>> => {
231	  const entries = await Promise.all(
232	    [...matchPlan.existingTemplateNames].map(async (templateName) => {
233	      const content = await readTemplateContent({
234	        app: plugin.app,
235	        templateName,
236	      });
237	      return content === null ? [] : [[templateName, content] as const];
238	    }),
239	  );
240	  return new Map(entries.flat());
