139	    selection.selectedNodeTypeIds.size > 0 ||
140	    selection.selectedRelationTypeIds.size > 0 ||
141	    selection.selectedRelationIds.size > 0 ||
142	    selection.selectedTemplateNames.size > 0;
143	
144	  const handleApplyImport = async (): Promise<void> => {
145	    setIsApplyingImport(true);
146	    const warnings: string[] = [];
147	    try {
148	      const result = await applySchemaImportSelection({
149	        plugin,
150	        loadedSchemaFile,
151	        selection: selection.asSelectionPayload(),
152	        mergePlan: mergePlan.asMergePlan(),
153	        onWarning: (message) => warnings.push(message),
154	      });
155	
156	      new Notice(buildImportCompleteMessage(result), 7000);
157	      if (warnings.length > 0) {
158	        new Notice(`Import warnings:\n${warnings.join("\n")}`, 6000);
159	      }
160	      onClose();
161	    } catch (error) {
162	      const message = error instanceof Error ? error.message : String(error);
163	      new Notice(`Failed to import schema: ${message}`, 6000);
164	      // Only the failure path stays mounted; the success path unmounted at onClose()
165	      setIsApplyingImport(false);
166	    }
167	  };
168	
169	  const handleAdvanceFromSelection = (): void => {
170	    if (!hasAnySelection) {
171	      new Notice("Select at least one item to import.");
172	      return;
173	    }
174	    if (selectedConflicts.length > 0) {
175	      setStep("choose");
176	      return;
177	    }
178	    void handleApplyImport();
179	  };
180	
181	  const isChoosingFields = step === "choose";
182	  const primaryLabel = isApplyingImport
183	    ? "Importing..."
184	    : isChoosingFields || selectedConflicts.length === 0
185	      ? "Import selected"
186	      : `Choose what to keep (${selectedConflicts.length})`;
187	
188	  return (
189	    <div>
190	      <h3 className="mb-2">
191	        {isChoosingFields ? "Choose what to keep" : "Import schema preview"}
192	      </h3>
193	      <p className="text-muted mb-4 text-sm">
194	        Source file: {loadedSchemaFile.sourcePath}
195	      </p>
196	
197	      {isChoosingFields ? (
198	        <SchemaConflictResolutionStep
199	          conflicts={selectedConflicts}
200	          mergePlan={mergePlan}
201	          sourceVaultName={schemaFile.vaultName}
202	        />
203	      ) : (
204	        <>
205	          <ImportSchemaPreviewSummary
206	            loadedSchemaFile={loadedSchemaFile}
207	            previewStats={previewStats}
208	          />
209	          <SchemaSelectionPanel
210	            source={source}
211	            selection={selection}
212	            nodeTypeNotes={buildExistingItemNotes({
213	              existingSchemaIds: loadedSchemaFile.matchPlan.existingNodeTypeIds,
214	              conflicts,
215	              category: "nodeType",
216	            })}
217	            relationTypeNotes={buildExistingItemNotes({
218	              existingSchemaIds:
219	                loadedSchemaFile.matchPlan.existingRelationTypeIds,
220	              conflicts,
221	              category: "relationType",
222	            })}
223	          />
224	        </>
225	      )}
226	
227	      <div className="mt-6 flex justify-between">
228	        <button
229	          type="button"
230	          className="px-4 py-2"
231	          onClick={
232	            isChoosingFields
233	              ? () => {
234	                  mergePlan.reset();
235	                  setStep("select");
236	                }
237	              : onResetPreview
238	          }
239	          disabled={isApplyingImport}
240	        >
241	          {isChoosingFields ? "Back" : "Choose another file"}
242	        </button>
243	        <button
244	          type="button"
245	          className="!bg-accent !text-on-accent rounded px-4 py-2"
246	          onClick={
247	            isChoosingFields
248	              ? () => void handleApplyImport()
249	              : handleAdvanceFromSelection
250	          }
251	          disabled={isApplyingImport}
252	        >
253	          {primaryLabel}
254	        </button>
255	      </div>
256	    </div>
257	  );
258	};
259	
260	const ImportSpecsContent = ({ plugin, onClose }: ImportSpecsModalProps) => {
261	  const [preview, setPreview] = useState<SpecImportPreview | null>(null);
262	  const [isSelectingFile, setIsSelectingFile] = useState(false);
263	  const [isApplyingImport, setIsApplyingImport] = useState(false);
264	
265	  const handleSelectSchemaFile = async (): Promise<void> => {
266	    setIsSelectingFile(true);
267	    try {
268	      const nextPreview = await pickAndPreviewSchemaImport({ plugin });
269	      setPreview(nextPreview);
270	    } catch (error) {
271	      if (error instanceof NativeFileDialogCancelledError) return;
272	      if (error instanceof ZodError) {
273	        const fields = error.issues.map((i) => i.path.join(".")).join(", ");
274	        new Notice(
275	          `Schema file is incompatible with this version of the plugin. Invalid or missing fields: ${fields}`,
276	          8000,
277	        );
278	        return;
279	      }
280	      const message = error instanceof Error ? error.message : String(error);
281	      new Notice(`Failed to load schema file: ${message}`, 6000);
282	    } finally {
283	      setIsSelectingFile(false);
284	    }
285	  };
286	
287	  if (!preview) {
288	    return (
289	      <div>
290	        <h3 className="mb-2">Import discourse graph schema</h3>
291	        <p className="text-muted mb-4 text-sm">
292	          Pick a <code>dg-schema-*.json</code> file from your computer to
293	          preview and choose exactly what to import.
294	        </p>
295	
296	        <div className="mb-4 rounded border p-3 text-sm">
297	          Same dependency rules as export apply here during selection.
298	        </div>
299	
300	        <div className="flex justify-between">
301	          <button type="button" className="px-4 py-2" onClick={onClose}>
302	            Cancel
303	          </button>
304	          <button
305	            type="button"
306	            className="!bg-accent !text-on-accent rounded px-4 py-2"
307	            onClick={() => void handleSelectSchemaFile()}
308	            disabled={isSelectingFile}
309	          >
310	            {isSelectingFile ? "Opening..." : "Choose schema file"}
311	          </button>
312	        </div>
313	      </div>
314	    );
315	  }
316	
317	  return (
318	    <ImportPreviewSelection
319	      plugin={plugin}
320	      loadedSchemaFile={preview.loadedSchemaFile}
321	      previewStats={preview.previewStats}
322	      conflicts={preview.conflicts}
323	      isApplyingImport={isApplyingImport}
324	      setIsApplyingImport={setIsApplyingImport}
325	      onResetPreview={() => setPreview(null)}
326	      onClose={onClose}
327	    />
328	  );
329	};
330	
331	export class ImportSpecsModal extends Modal {
332	  private plugin: DiscourseGraphPlugin;
333	  private root: Root | null = null;
334	
335	  constructor(plugin: DiscourseGraphPlugin) {
336	    super(plugin.app);
337	    this.plugin = plugin;
338	  }
339	
340	  onOpen(): void {
341	    this.contentEl.empty();
342	    this.root = createRoot(this.contentEl);
343	    this.root.render(
344	      <StrictMode>
345	        <ImportSpecsContent plugin={this.plugin} onClose={() => this.close()} />
346	      </StrictMode>,
347	    );
348	  }
349	
350	  onClose(): void {
351	    if (this.root) {
352	      this.root.unmount();
353	      this.root = null;
354	    }
355	  }
356	}
