1	import { useEffect, useMemo, useState } from "react";
2	import type {
3	  DiscourseNode,
4	  DiscourseRelation,
5	  DiscourseRelationType,
6	  SchemaSelection,
7	} from "~/types";
8	
9	export type SchemaSelectionSource = {
10	  nodeTypes: Pick<DiscourseNode, "id" | "name" | "template">[];
11	  relationTypes: Pick<DiscourseRelationType, "id" | "label">[];
12	  relationTriples: Pick<
13	    DiscourseRelation,
14	    "id" | "sourceId" | "destinationId" | "relationshipTypeId"
15	  >[];
16	  templateNames: string[];
17	};
18	
19	type SelectionToggleResult = {
20	  ok: boolean;
21	  reason?: string;
22	};
23	
24	export type SchemaSelectionState = {
25	  selectedNodeTypeIds: Set<string>;
26	  selectedRelationTypeIds: Set<string>;
27	  selectedRelationIds: Set<string>;
28	  selectedTemplateNames: Set<string>;
29	  requiredNodeTypeIds: Set<string>;
30	  requiredRelationTypeIds: Set<string>;
31	  selectAllNodeTypes: () => void;
32	  deselectOptionalNodeTypes: () => void;
33	  toggleNodeType: (
34	    nodeTypeId: string,
35	    shouldSelect: boolean,
36	  ) => SelectionToggleResult;
37	  selectAllRelationTypes: () => void;
38	  deselectOptionalRelationTypes: () => void;
39	  toggleRelationType: (
40	    relationTypeId: string,
41	    shouldSelect: boolean,
42	  ) => SelectionToggleResult;
43	  selectAllRelationTriples: () => void;
44	  deselectAllRelationTriples: () => void;
45	  toggleRelationTriple: (relationId: string, shouldSelect: boolean) => void;
46	  selectAllTemplates: () => void;
47	  deselectAllTemplates: () => void;
48	  toggleTemplate: (templateName: string, shouldSelect: boolean) => void;
49	  asSelectionPayload: () => SchemaSelection;
50	};
51	
52	const updateSet = (
53	  previousSet: Set<string>,
54	  id: string,
55	  shouldSelect: boolean,
56	): Set<string> => {
57	  const nextSet = new Set(previousSet);
58	  if (shouldSelect) {
59	    nextSet.add(id);
60	  } else {
61	    nextSet.delete(id);
62	  }
63	  return nextSet;
64	};
65	
66	export const getReferencedTemplateNames = (
