    expect(settings.nodeTypes.map((type) => type.id)).toEqual(["local"]);
    expect(settings.relationTypes.map((type) => type.id)).toEqual(["local-r"]);
    expect(settings.discourseRelations).toMatchObject([
      {
        sourceId: "local",
