  plugin.addCommand({
import { z } from "zod";
import type {
  DiscourseNode,
  DiscourseRelation,
  DiscourseRelationType,
  DiscourseSchemaFile,
  DiscourseSchemaTemplate,
} from "~/types";
import { toTldrawColor } from "~/utils/tldrawColors";

export const DG_SCHEMA_EXPORT_VERSION = 1;

const discourseNodeSchema: z.ZodType<DiscourseNode> = z
  .object({
    id: z.string(),
    name: z.string(),
    format: z.string(),
    template: z.string().optional(),
    description: z.string().optional(),
    shortcut: z.string().optional(),
    color: z.string().optional(),
    tag: z.string().optional(),
    keyImage: z.boolean().optional(),
    folderPath: z.string().optional(),
    created: z.number(),
    modified: z.number(),
    importedFromRid: z.string().optional(),
    authorId: z.number().optional(),
  })
  .passthrough();

const relationImportStatusSchema = z.enum(["provisional", "accepted"]);

const discourseRelationTypeSchema: z.ZodType<
  DiscourseRelationType,
  z.ZodTypeDef,
  unknown
> = z
  .object({
    id: z.string(),
    label: z.string(),
    complement: z.string(),
    // Coerced, not rejected: vaults predating tldraw color names hold hex, and export copies settings verbatim, so a strict enum here fails a file the apply path could read.
    color: z
      .unknown()
      .transform((value) =>
        toTldrawColor(typeof value === "string" ? value : undefined),
      ),
    created: z.number(),
    modified: z.number(),
    importedFromRid: z.string().optional(),
    status: relationImportStatusSchema.optional(),
    authorId: z.number().optional(),
  })
  .passthrough();

const discourseRelationSchema: z.ZodType<DiscourseRelation> = z
  .object({
    id: z.string(),
    sourceId: z.string(),
    destinationId: z.string(),
    relationshipTypeId: z.string(),
    created: z.number(),
    modified: z.number(),
    importedFromRid: z.string().optional(),
    status: relationImportStatusSchema.optional(),
    authorId: z.number().optional(),
  })
  .passthrough();

const templateExportSchema: z.ZodType<DiscourseSchemaTemplate> = z
  .object({ name: z.string(), content: z.string() })
  .passthrough();

export const dgSchemaFileSchema: z.ZodType<
  DiscourseSchemaFile,
  z.ZodTypeDef,
  unknown
> = z
  .object({
    version: z.literal(DG_SCHEMA_EXPORT_VERSION),
    exportedAt: z.string(),
    pluginVersion: z.string(),
    vaultName: z.string(),
    vaultId: z.string(),
    nodeTypes: z.array(discourseNodeSchema),
    relationTypes: z.array(discourseRelationTypeSchema),
    discourseRelations: z.array(discourseRelationSchema),
    templates: z.array(templateExportSchema),
  })
  .passthrough();

const normalizeToKebabCase = (value: string): string => {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .replace(/-{2,}/g, "-");
};

export const getDgSchemaFileName = (vaultName?: string): string => {
  const normalizedVaultName = vaultName ? normalizeToKebabCase(vaultName) : "";
  const safeVaultName =
    normalizedVaultName.length > 0 ? normalizedVaultName : "vault";
// ENG-2114 "insert active search result as a link at cursor", as scenario modules.
//   run.mjs --marker "insert link at cursor" --scenario examples/insert-link-at-cursor.mjs
const MODAL = ".dg-node-search-modal";
const INPUT = `${MODAL} [role="textbox"]`; // contenteditable chips input, not an <input>
const SCRATCH = "insert-link-scratch.md";
const ORIGINAL = "before| after\n";

const openSearch = async ({ client, json, vault }) => {
  await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:open-node-search`)});`);
  await client.waitFor(`!!document.querySelector(${json(INPUT)})`, { label: "search input rendered" });
};

const footerLabels = ({ client, json }) =>
  client.evaluate(`return Array.from(document.querySelectorAll(${json(`${MODAL} .dg-search-footer-action`)}))
    .map((el) => el.textContent.trim());`);

const linkConfig = ({ client }) =>
  client.evaluate(`return { useMarkdownLinks: app.vault.getConfig("useMarkdownLinks"),
    newLinkFormat: app.vault.getConfig("newLinkFormat") };`);

const setLinkConfig = ({ client, json }, cfg) =>
  client.evaluate(`app.vault.setConfig("useMarkdownLinks", ${json(cfg.useMarkdownLinks)});
    app.vault.setConfig("newLinkFormat", ${json(cfg.newLinkFormat)}); return true;`);

// A discourse node (has nodeTypeId) outside _verify, so the search has something to find.
const nodeTitle = ({ client }) =>
  client.evaluate(`return app.vault.getMarkdownFiles()
    .find((f) => !f.path.startsWith("_verify/") && app.metadataCache.getFileCache(f)?.frontmatter?.nodeTypeId)
    ?.basename;`);

const openScratchAtCol6 = async (ctx) => {
  const { client, json } = ctx;
  const p = await ctx.writeNote(SCRATCH, ORIGINAL);
  await client.evaluate(`return (async () => {
    const leaf = app.workspace.getLeaf("tab");
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(p)}), { state: { mode: "source" } });
    app.workspace.setActiveLeaf(leaf, { focus: true });
    leaf.view.editor.focus();
    leaf.view.editor.setCursor({ line: 0, ch: 6 });
    return true;
  })();`);
  return p;
};

