        same(result.relationTypes, ["Precedes", "precedes"]) &&
        same(result.triples, [`${NODE_B} > ${REL_B} > ${NODE_B}`]) &&
        noWarning(result),
      actual: JSON.stringify({ summary: preview.summary, ...result }),
