    name: "S2 Deselecting the first variant keeps the second and its triple",
    input: "same file; untick Milestone and Precedes, keep milestone, precedes and the triple; import",
    expected: "only milestone and precedes created, triple created; no warning",
    setup: snapshot,
    run: async (ctx) => {
      const preview = await openPreview(ctx);
      await clickAt(ctx, checkbox(ctx.json, "Milestone"), "Milestone checkbox");
      await clickAt(ctx, checkbox(ctx.json, "Precedes"), "Precedes checkbox");
