    },
    expect: ({ preview, result }) => ({
      pass:
        !preview.rows.some((r) => r.includes("in vault")) &&
        preview.summary.every((s) => s.includes("2 total (2 new, 0 existing)")) &&
        same(result.nodeTypes, ["Milestone", "milestone"]) &&
        same(result.relationTypes, ["Precedes", "precedes"]) &&
        same(result.triples, [`${NODE_B} > ${REL_B} > ${NODE_B}`]) &&
