        same(result.triples, [`${NODE_B} > ${REL_B} > ${NODE_B}`]) &&
        noWarning(result),
      actual: JSON.stringify({ unticked, ...result }),
    }),
    teardown: restore,
  },
  {
    name: "S3 A vault type with the same name still takes the merge path",
